/// Returns the lower-bound insertion index for `x` within the sorted slice range [lo, hi),
/// i.e., the smallest k in [lo, hi] such that:
/// - for all r in [lo, k): a[r] < x
/// - for all r in [k, hi): a[r] >= x
///
/// Preconditions expected by the problem statement:
/// - 0 <= lo <= hi <= a.len()
/// - a[lo..hi] is sorted in nondecreasing order
fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    debug_assert!(lo <= hi && hi <= a.len());

    let mut l = lo;
    let mut r = hi; // exclusive

    while l < r {
        let m = l + (r - l) / 2;
        if a[m] < x {
            l = m + 1;
        } else {
            r = m;
        }
    }

    l
}

